INSERT INTO mes_genealogy_material (material_code, display_name, uom) SELECT 'MAT-WIDGET-A01', 'Assembly widget A01', 'EA' WHERE NOT EXISTS (SELECT 1 FROM mes_genealogy_material WHERE material_code = 'MAT-WIDGET-A01'); INSERT INTO mes_genealogy_material (material_code, display_name, uom) SELECT 'MAT-RAW-A01', 'Raw material A01', 'KG' WHERE NOT EXISTS (SELECT 1 FROM mes_genealogy_material WHERE material_code = 'MAT-RAW-A01'); INSERT INTO mes_genealogy_material (material_code, display_name, uom) SELECT 'MAT-WIP-A01', 'WIP material A01', 'EA' WHERE NOT EXISTS (SELECT 1 FROM mes_genealogy_material WHERE material_code = 'MAT-WIP-A01'); INSERT INTO mes_bom_header (bom_id, parent_material_code, revision, display_name, status) SELECT 'BOM-WIDGET-A01-A', 'MAT-WIDGET-A01', 'A', 'Widget A01 BoM rev A', 'active' WHERE NOT EXISTS (SELECT 1 FROM mes_bom_header WHERE bom_id = 'BOM-WIDGET-A01-A'); INSERT INTO mes_bom_line (bom_id, line_no, component_material_code, quantity, uom) SELECT 'BOM-WIDGET-A01-A', 10, 'MAT-RAW-A01', 2.000, 'KG' WHERE NOT EXISTS (SELECT 1 FROM mes_bom_line WHERE bom_id = 'BOM-WIDGET-A01-A' AND line_no = 10); INSERT INTO mes_bom_line (bom_id, line_no, component_material_code, quantity, uom) SELECT 'BOM-WIDGET-A01-A', 20, 'MAT-WIP-A01', 1.000, 'EA' WHERE NOT EXISTS (SELECT 1 FROM mes_bom_line WHERE bom_id = 'BOM-WIDGET-A01-A' AND line_no = 20); INSERT INTO mes_operation_def (operation_id, routing_id, name, work_center, sequence_no) SELECT 'OP-CUT', 'RT-WIDGET-A01', 'Cut raw material', 'WC-CUT', 10 WHERE NOT EXISTS (SELECT 1 FROM mes_operation_def WHERE operation_id = 'OP-CUT'); INSERT INTO mes_operation_def (operation_id, routing_id, name, work_center, sequence_no) SELECT 'OP-ASSEMBLE', 'RT-WIDGET-A01', 'Assemble widget', 'WC-ASSEMBLY', 20 WHERE NOT EXISTS (SELECT 1 FROM mes_operation_def WHERE operation_id = 'OP-ASSEMBLE'); INSERT INTO mes_operation_def (operation_id, routing_id, name, work_center, sequence_no) SELECT 'OP-TEST', 'RT-WIDGET-A01', 'Test widget', 'WC-TEST', 30 WHERE NOT EXISTS (SELECT 1 FROM mes_operation_def WHERE operation_id = 'OP-TEST'); INSERT INTO mes_operation_edge (routing_id, predecessor_op, successor_op) SELECT 'RT-WIDGET-A01', 'OP-CUT', 'OP-ASSEMBLE' WHERE NOT EXISTS (SELECT 1 FROM mes_operation_edge WHERE routing_id = 'RT-WIDGET-A01' AND predecessor_op = 'OP-CUT' AND successor_op = 'OP-ASSEMBLE'); INSERT INTO mes_operation_edge (routing_id, predecessor_op, successor_op) SELECT 'RT-WIDGET-A01', 'OP-ASSEMBLE', 'OP-TEST' WHERE NOT EXISTS (SELECT 1 FROM mes_operation_edge WHERE routing_id = 'RT-WIDGET-A01' AND predecessor_op = 'OP-ASSEMBLE' AND successor_op = 'OP-TEST'); INSERT INTO mes_operation_status (wo_number, operation_id, status) SELECT 'WO-LINE-A01-001', 'OP-CUT', 'complete' WHERE NOT EXISTS (SELECT 1 FROM mes_operation_status WHERE wo_number = 'WO-LINE-A01-001' AND operation_id = 'OP-CUT'); INSERT INTO mes_operation_status (wo_number, operation_id, status) SELECT 'WO-LINE-A01-001', 'OP-ASSEMBLE', 'ready' WHERE NOT EXISTS (SELECT 1 FROM mes_operation_status WHERE wo_number = 'WO-LINE-A01-001' AND operation_id = 'OP-ASSEMBLE'); INSERT INTO mes_operation_status (wo_number, operation_id, status) SELECT 'WO-LINE-A01-001', 'OP-TEST', 'pending' WHERE NOT EXISTS (SELECT 1 FROM mes_operation_status WHERE wo_number = 'WO-LINE-A01-001' AND operation_id = 'OP-TEST');
